// Hand-written `knex` stub for the flowatlas fixture suite. It is installed as the
// ORM's dependency rather than the application's: nothing under `src` imports it
// and the fixture's manifest does not name it, which is how a project that reaches
// knex only through its ORM is installed.

export interface QueryBuilder extends Promise<unknown[]> {
  from(table: string): QueryBuilder;
  where(column: string, value: unknown): QueryBuilder;
  select(...columns: string[]): QueryBuilder;
  first(): Promise<unknown>;
  update(row: Record<string, unknown>): Promise<number>;
}

export interface Knex {
  (table: string | Record<string, string>): QueryBuilder;
  select(...columns: string[]): QueryBuilder;
}

export declare namespace Knex {
  interface Transaction extends Knex {
    commit(): Promise<void>;
  }
}
